const input = $input.first().json;

const rawText =
  input.contract_text ||
  input.text ||
  input.extracted_text ||
  "";

const normalizedText = String(rawText)
  .replace(/\r\n/g, "\n")
  .replace(/[ \t]+/g, " ")
  .replace(/\n{3,}/g, "\n\n")
  .trim();

return [
  {
    json: {
      contract_text: normalizedText,
      character_count: normalizedText.length,
      word_count: normalizedText
        .split(/\s+/)
        .filter(Boolean)
        .length
    }
  }
];

const raw = $input.first().json.output;

try {
  let cleaned = String(raw)
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  const start = cleaned.indexOf("{");
  const end = cleaned.lastIndexOf("}");

  if (start === -1 || end === -1) {
    throw new Error("No JSON object found");
  }

  cleaned = cleaned.substring(start, end + 1);

  return [
    {
      json: {
        ...JSON.parse(cleaned),
        parse_status: "success"
      }
    }
  ];

} catch (error) {
  return [
    {
      json: {
        parse_status: "failed",
        parse_error: error.message,
        raw_output: raw
      }
    }
  ];
}

